/**
 * Get Organization License History
 * Reads every change ever made to an organization's license, newest first and paginated: the template it was instantiated from, and each later adjustment naming the license field, the value it held and the value it was given.
 * The history is append-only and immutable. There is no route that edits or removes an entry, so "what was this customer given, and when" keeps the same answer for the lifetime of the organization. Deleting the organization takes its history with it.
 * An organization that has never been licensed reads as an empty history rather than as a 404 — nothing has happened to it yet, which is a fact rather than an absence. A 404 means no such organization.
 */
export const getOrganizationLicenseHistory = <ThrowOnError extends boolean = false>(options: Options<GetOrganizationLicenseHistoryData, ThrowOnError>) => {
    return (options.client ?? client).get<GetOrganizationLicenseHistoryResponses, GetOrganizationLicenseHistoryErrors, ThrowOnError>({
        security: [
            {
                scheme: 'bearer',
                type: 'http'
            },
            {
                name: 'X-Product-API-Key',
                type: 'apiKey'
            }
        ],
        url: '/v1/products/{product_id}/organizations/{organization_id}/license/history',
        ...options
    });
};

/**
 * Report Organization Usage
 * Records what an organization has used, as an absolute snapshot. Every report is kept as an immutable observation, and Anchor never adds them together, so reporting the same value twice changes nothing.
 * The report is checked for four things: the product's license schema declares the key, the field is a limit, the value is a finite non-negative number, and the window is coherent and no longer than a year. The license field's own rules are deliberately not applied. Rules bound what a limit may be set to, never what usage turns out to be, so a value past the organization's limit is stored as reported.
 * The organization does not need a license. Usage is what happened, and it stays true whether or not a limit was granted.
 */
export const reportOrganizationUsage = <ThrowOnError extends boolean = false>(options: Options<ReportOrganizationUsageData, ThrowOnError>) => {
    return (options.client ?? client).post<ReportOrganizationUsageResponses, ReportOrganizationUsageErrors, ThrowOnError>({
        security: [
            {
                scheme: 'bearer',
                type: 'http'
            },
            {
                name: 'X-Product-API-Key',
                type: 'apiKey'
            }
        ],
        url: '/v1/products/{product_id}/organizations/{organization_id}/license/usage',
        ...options,
        headers: {
            'Content-Type': 'application/json',
            ...options.headers
        }
    });
};

/**
 * Get Organization Usage Series
 * Reads an organization's usage history for one license field: filtered by key and time range, and paginated. Granularity selects a level of the continuous-aggregate cascade — MINUTE, HOUR or DAY — each reporting the last observation per bucket, never a sum or an average, because the values are snapshots.
 * This is a deliberately separate read from the license state: a large paginated series and a small hot cacheable read want different shapes. This endpoint is not cached, and reading it never touches the license state read's cache.
 * Interpreting the series against a limit — deciding whether an organization is within or past it — is not this endpoint's job. It returns the series as stored; that judgment stays in the license state read.
 */
export const getOrganizationUsageSeries = <ThrowOnError extends boolean = false>(options: Options<GetOrganizationUsageSeriesData, ThrowOnError>) => {
    return (options.client ?? client).get<GetOrganizationUsageSeriesResponses, GetOrganizationUsageSeriesErrors, ThrowOnError>({
        security: [
            {
                scheme: 'bearer',
                type: 'http'
            },
            {
                name: 'X-Product-API-Key',
                type: 'apiKey'
            }
        ],
        url: '/v1/products/{product_id}/organizations/{organization_id}/license/usage/series',
        ...options
    });
};

